151: export async function enqueueJevExample(env: Env, row: JevExampleRow): Promise<void> {
152:   if (row.provider === "off") return;
153: 
154:   // Gate the corpus here rather than at flush time. All three use cases funnel
155:   // through this function, and a row that never enters the queue means the
156:   // secret is never written to D1 and can never reach HuggingFace. Scrubbing in
157:   // flushJevExamples instead would leave it sitting in the queue forever.
158:   let safe: JevExampleRow;
159:   try {
160:     const { row: scrubbed, findings } = scrubJevRow(row as unknown as Record<string, unknown>);
161:     safe = scrubbed as unknown as JevExampleRow;
162:     if (findings.length) {
163:       // Rule names only. The values are the thing being protected.
164:       console.warn(
165:         `enqueueJevExample: redacted [${summariseFindings(findings)}] from ${row.use_case} row ${row.id}`,
166:       );
167:     }
168:   } catch (err) {
169:     // Fail closed: an unvetted row is exactly what leaked the admin passkey to a
170:     // public dataset. Dropping one training example is cheaper than that.
171:     console.error("enqueueJevExample: redaction failed, refusing to enqueue:", String(err));
172:     return;
173:   }
174: 
175:   try {
176:     await env.DB.prepare(
177:       `INSERT INTO jev_examples (id, use_case, payload, status, attempts, error, created_at)
178:        VALUES (?, ?, ?, 'pending', 0, NULL, ?)`,
179:     )
180:       .bind(safe.id, safe.use_case, JSON.stringify(safe), safe.created_at)
181:       .run();
182:   } catch (err) {
183:     console.error("enqueueJevExample failed:", String(err));
184:   }
185: }
