197: export async function jevQueueStats(env: Env, scope?: string): Promise<QueueStats> {
198:   const { results } = await env.DB.prepare(
199:     `SELECT status, COUNT(*) AS n FROM jev_examples GROUP BY status`,
200:   ).all<{ status: string; n: number }>();
201:   const byUseCase = await env.DB.prepare(
202:     `SELECT use_case, COUNT(*) AS n FROM jev_examples GROUP BY use_case`,
203:   ).all<{ use_case: string; n: number }>();
204:   const last = await env.DB.prepare(`SELECT MAX(uploaded_at) AS t FROM jev_examples`).first<{ t: number | null }>();
205:   const statusMap = new Map((results || []).map((r) => [r.status, r.n]));
206:   const by_use_case: Record<string, number> = {};
207:   for (const row of byUseCase.results || []) by_use_case[row.use_case] = row.n;
208:   return {
209:     pending: statusMap.get("pending") ?? 0,
210:     uploaded: statusMap.get("uploaded") ?? 0,
211:     error: statusMap.get("error") ?? 0,
212:     total: [...statusMap.values()].reduce((a, b) => a + b, 0),
213:     by_use_case,
214:     last_flush_at: last?.t ?? null,
215:     next_dataset: datasetRepo(env),
216:   };
217: }
