295: async function hfGet(env: Env, path: string): Promise<Response> {
296:   return fetch(`${HF_API}/datasets/${datasetRepo(env)}/resolve/main/${path}`, {
297:     headers: { authorization: `Bearer ${env.HF_TOKEN}` },
298:   });
299: }
