301: async function readFile(env: Env, path: string): Promise<string | null> {
302:   const res = await hfGet(env, path);
303:   if (res.status === 404) return null;
304:   if (!res.ok) throw new Error(`read ${path}: HTTP ${res.status}`);
305:   return await res.text();
