313: function base64Utf8(input: string): string {
314:   const bytes = new TextEncoder().encode(input);
315:   let binary = "";
316:   const CHUNK = 0x8000;
317:   for (let i = 0; i < bytes.length; i += CHUNK) {
318:     binary += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
319:   }
320:   return btoa(binary);
321: }
