323: // HF's commit API: NDJSON with a header line followed by one base64 file line each.
324: // (POST /api/datasets/{repo}/commit/{revision})
325: async function createCommit(env: Env, files: UploadFile[], summary: string): Promise<Response> {
326:   const lines = [JSON.stringify({ key: "header", value: { summary, description: "" } })];
327:   for (const f of files) {
328:     lines.push(JSON.stringify({ key: "file", value: { path: f.path, encoding: "base64", content: base64Utf8(f.content) } }));
329:   }
330:   return fetch(`${HF_API}/api/datasets/${datasetRepo(env)}/commit/main`, {
331:     method: "POST",
332:     headers: { authorization: `Bearer ${env.HF_TOKEN}`, "content-type": "application/x-ndjson" },
333:     body: lines.join("\n") + "\n",
334:   });
335: }
