339:     headers: { authorization: `Bearer ${env.HF_TOKEN}` },
340:   });
341:   if (exists.ok) return;
342:   const res = await fetch(`${HF_API}/api/repos/create`, {
343:     method: "POST",
344:     headers: { "content-type": "application/json", authorization: `Bearer ${env.HF_TOKEN}` },
345:     body: JSON.stringify({ name: datasetRepo(env).split("/")[1], type: "dataset", private: false }),
346:   });
347:   if (!res.ok) throw new Error(`create repo: HTTP ${res.status}: ${(await res.text()).slice(0, 200)}`);
348: }
