360: export async function flushJevExamples(env: Env, limit = 200): Promise<FlushResult> {
361:   if (!env.HF_TOKEN) return { dataset: datasetRepo(env), batch: 0, uploaded_rows: 0, queue_remaining: 0, total_rows: 0, commit_ok: false, error: "HF_TOKEN not set" };
362: 
363:   const { results } = await env.DB.prepare(
364:     `SELECT id, use_case, payload FROM jev_examples
365:       WHERE status = 'pending' ORDER BY created_at ASC LIMIT ?`,
366:   )
367:     .bind(limit)
368:     .all<{ id: string; use_case: string; payload: string }>();
369:   const pending = results || [];
370:   if (!pending.length) {
371:     const stats = await jevQueueStats(env);
372:     return { dataset: datasetRepo(env), batch: 0, uploaded_rows: 0, queue_remaining: 0, total_rows: stats.uploaded, commit_ok: true };
373:   }
374: 
375:   const rows: JevExampleRow[] = pending.map((p) => JSON.parse(p.payload) as JevExampleRow);
376:   const batchId = now();
377: 
378:   const [existingFile, existingMeta, existingReadme] = await Promise.all([
379:     readFile(env, "train.jsonl").catch((e) => { throw e; }),
380:     readFile(env, "metadata.json").catch(() => null),
381:     readFile(env, "README.md").catch(() => null),
382:   ]);
383: 
384:   const seen = new Set<string>();
385:   const newRows: JevExampleRow[] = [];
386:   if (existingFile) {
387:     for (const line of existingFile.split("\n")) {
388:       if (!line.trim()) continue;
389:       try {
390:         const r = JSON.parse(line) as { id?: string };
391:         if (r.id) seen.add(r.id);
392:       } catch {
393:         /* skip malformed line */
394:       }
395:     }
396:   }
397:   for (const row of rows) {
398:     if (seen.has(row.id)) continue;
399:     newRows.push(row);
400:     seen.add(row.id);
401:   }
402: 
403:   if (!newRows.length) {
404:     const ph = pending.map(() => "?").join(",");
405:     await env.DB.prepare(`UPDATE jev_examples SET status = 'uploaded', uploaded_at = ? WHERE id IN (${ph})`)
406:       .bind(now(), ...pending.map((p) => p.id))
407:       .run();
408:     const stats = await jevQueueStats(env);
409:     return { dataset: datasetRepo(env), batch: 0, uploaded_rows: 0, queue_remaining: stats.pending, total_rows: stats.uploaded, commit_ok: true };
410:   }
411: 
412:   const appended = (existingFile ? existingFile.replace(/\n?$/, "\n") : "") + newRows.map((r) => JSON.stringify(r)).join("\n") + "\n";
413: 
414:   // metadata.json: merge running totals with this batch.
415:   const meta: Record<string, any> = { ...META_DEFAULTS, ...(existingMeta ? JSON.parse(existingMeta) : {}) };
416:   meta.rows_total = (meta.rows_total ?? 0) + newRows.length;
417:   meta.last_flush_at = batchId;
418:   const createdTimes = newRows.map((r) => r.created_at).filter((t) => typeof t === "number");
419:   const first = createdTimes.length ? Math.min(...createdTimes) : null;
420:   const last = createdTimes.length ? Math.max(...createdTimes) : null;
421:   meta.first_row_at = meta.first_row_at ?? first ?? now();
422:   meta.last_row_at = last ?? now();
423:   const useCaseCounts: Record<string, number> = {};
424:   const providerCounts: Record<string, number> = {};
425:   for (const r of newRows) {
426:     useCaseCounts[r.use_case] = (useCaseCounts[r.use_case] ?? 0) + 1;
427:     providerCounts[r.provider] = (providerCounts[r.provider] ?? 0) + 1;
428:   }
429:   for (const [k, v] of Object.entries(useCaseCounts)) meta.by_use_case[k] = (meta.by_use_case[k] ?? 0) + v;
430:   for (const [k, v] of Object.entries(providerCounts)) meta.providers[k] = (meta.providers[k] ?? 0) + v;
431:   meta.updated_at = now();
432: 
433:   await ensureRepo(env);
434: 
435:   const files: UploadFile[] = [];
436:   const needsReadme = !existingReadme;
437:   files.push({ path: "train.jsonl", content: appended });
438:   files.push({ path: "metadata.json", content: JSON.stringify(meta, null, 2) });
439:   if (needsReadme) files.push({ path: "README.md", content: README });
440: 
441:   const upload = await createCommit(
442:     env,
443:     files,
444:     `DGUI_HYPERMEM-JEV flush ${batchId}: +${newRows.length} rows (${Object.entries(useCaseCounts).map(([k, v]) => `${k}:${v}`).join(", ")})`,
445:   );
446:   if (!upload.ok) {
447:     const body = (await upload.text()).slice(0, 300);
448:     throw new Error(`hf upload: HTTP ${upload.status}: ${body}`);
449:   }
450: 
451:   const ph = pending.map(() => "?").join(",");
