392: async function loadVisits(){
393:   var box=document.getElementById('visit-spark');
394:   try{
395:     var r=await fetch('/api/admin/visits',{headers:getApiHeaders({})});
396:     var d=await r.json();
397:     if(d.error) return;
398:     document.getElementById('sys-visits-today').textContent=d.today;
399:     document.getElementById('sys-visits-total').textContent=d.total;
400:     document.getElementById('spark-sum').textContent='last 30d: '+d.last_30;
401:     var days=d.days||[];
402:     // The server always emits a dense 30-day series, so this is unreachable in
403:     // practice. Draw the same kind of explanation the activity panel does rather
404:     // than leaving a silent blank chart if the response shape ever changes.
405:     if(!days.length){
406:       box.innerHTML='<div class="act-empty">No visit data yet.</div>';
407:       return;
408:     }
409:     var peak=Math.max.apply(null,days.map(function(x){return x.count}).concat([1]));
410:     box.innerHTML=days.map(function(x){
411:       var h=Math.max(1,Math.round(x.count/peak*72));
412:       var title=x.day+' - '+x.count+' visit'+(x.count===1?'':'s');
413:       return '<div class="spark-bar" data-zero="'+(x.count?0:1)+'" style="height:'+h+'px" title="'+title+'"></div>';
414:     }).join('');
415:   }catch(e){/* fail open: the panel just shows nothing */}
416: }
