418: /* --- activity dot-and-connector visualiser --- */
419: const ACT_COLORS={add:'#4ade80',update:'#22c7dc',supersede:'#f59e0b',forget:'#f87171',search:'#a78bfa'};
420: async function loadActivity(){
421:   var canvas=document.getElementById('act-canvas');
422:   try{
423:     var r=await fetch('/api/admin/activity?limit=60',{headers:getApiHeaders({})});
424:     var d=await r.json();
425:     if(d.error) return;
426:     var nodes=d.nodes||[];
427:     var counts=d.counts||{};
428:     document.getElementById('activity-summary').textContent=
429:       Object.keys(counts).map(function(k){return k+' '+counts[k]}).join(' · ')||'none';
430:     document.getElementById('act-legend').innerHTML=Object.keys(ACT_COLORS).map(function(k){
431:       return '<span><i style="background:'+ACT_COLORS[k]+'"></i>'+k+(counts[k]?' ('+counts[k]+')':'')+'</span>';
432:     }).join('');
433:     if(!nodes.length){
434:       canvas.innerHTML='<div class="act-empty">No memory activity recorded in the last 7 days.</div>';
435:       return;
436:     }
437:     var W=canvas.clientWidth||600, H=canvas.clientHeight||220;
438:     // Oldest left -> newest right, so the connectors read as a timeline.
439:     var ordered=nodes.slice().reverse();
440:     var t0=ordered[0].at, t1=ordered[ordered.length-1].at||t0+1;
441:     var span=Math.max(t1-t0,1);
442:     var pts=ordered.map(function(n){
443:       var x=24+((n.at-t0)/span)*(W-48);
444:       // search events carry a result count; stack them on a sine so overlapping
445:       // dots at the same instant stay individually visible.
446:       var jitter=n.results?Math.sin((n.at%997)/997*Math.PI*2)*34:0;
447:       var y=H/2+jitter;
448:       return {n:n,x:x,y:y};
449:     });
450:     var svg='<svg class="act-svg" viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="none">';
451:     for(var i=1;i<pts.length;i++){
452:       var a=pts[i-1],b=pts[i];
453:       var stroke=(ACT_COLORS[b.n.kind]||'#22c7dc');
454:       svg+='<line x1="'+a.x+'" y1="'+a.y+'" x2="'+b.x+'" y2="'+b.y+'" stroke="'+stroke+'" stroke-width="1" opacity=".35"/>';
455:     }
456:     svg+='</svg>';
457:     var html=svg;
458:     pts.forEach(function(p){
459:       var color=ACT_COLORS[p.n.kind]||'#22c7dc';
460:       var size=p.n.results?10+Math.min(10,p.n.results):8;
461:       var when=new Date(p.n.at).toLocaleString();
462:       var tip=p.n.kind+' · '+when+(p.n.results?' · '+p.n.results+' results':'');
463:       html+='<div class="act-node" style="left:'+p.x+'px;top:'+p.y+'px">'
464:         +'<div class="act-dot" style="width:'+size+'px;height:'+size+'px;background:'+color+';color:'+color+'"></div>'
465:         +'<div class="act-tip">'+esc(tip)+'</div></div>';
466:     });
467:     canvas.innerHTML=html;
468:   }catch(e){canvas.innerHTML='<div class="act-empty">Activity unavailable.</div>'}
469: }
