}

async function checkServices(){
  const set=(id,ok)=>{
    const el=document.getElementById(id);
    if(!el) return;
    el.classList.remove('ok','down','unknown');
    el.classList.add(ok?'ok':'down');
    el.querySelector('span:last-child').textContent=ok?'ONLINE':'DOWN';
  };
  try{
    const h=await fetch('/health',{cache:'no-store'});
    set('svc-health', h.ok);
  }catch(e){ set('svc-health', false); }
  try{
