Implementation details for service status markup: `.service-status` element has `<span class="dot"></span><span>CHECKING</span>`. I'll set className and innerHTML.

checkServices:
```js
async function checkServices(){
  const set=(id,state,text)=>{
    const el=document.getElementById(id);
    if(!el) return;
    el.className='service-status '+state;
    const label=el.querySelector('span:last-child');
    if(label) label.textContent=text;
  };
  // health
  try{
    const r=await fetch('/health',{cache:'no-store'});
    const d=await r.json();
    set('svc-health', r.ok&&d.status==='ok'?'ok':'down', r.ok?('ONLINE · '+String(d.jev_mode||'?').toUpperCase()):'DOWN');
  }catch(e){ set('svc-health','down','DOWN'); }
  // mcp
  try{
