/* --- solution lamp ---
   Lights only when /api/solution-signal reports the store already holds a
   matching memory. That endpoint returns a boolean and a count, never content,
   so this reveals nothing about what is actually stored. */
const lampEl=document.getElementById('lamp');
const lampResult=document.getElementById('lamp-result');
const lampSub=document.getElementById('lamp-sub');
function lampState(cls,text){
  lampEl.className='lamp'+(cls?' '+cls:'');
  if(text!==undefined) lampSub.textContent=text;
}
document.getElementById('lamp-form').addEventListener('submit',async function(ev){
  ev.preventDefault();
  const q=document.getElementById('lamp-q').value.trim();
  const btn=this.querySelector('button');
  if(q.length<4){
    lampState('','Give it a few more words so the check means something.');
    lampResult.classList.remove('show');
    return;
  }
  btn.disabled=true;
  lampState('checking','Checking HyperMem memory...');
  // Hide AND clear. Leaving the previous answer on screen while a new check runs
  // shows the old verdict against the new question, and clearing only the class
  // (not the text) leaves it readable if the stylesheet fails.
  lampResult.classList.remove('show');
  lampResult.innerHTML='';
  try{
    const r=await fetch('/api/solution-signal?q='+encodeURIComponent(q));
    const d=await r.json();
    if(d.has){
      lampState('lit','HyperMem already holds '+d.count+' matching memor'+(d.count===1?'y':'ies')+'.');
      lampResult.innerHTML='A token lets you read the solution itself.';
      lampResult.classList.add('show');
    }else if(d.confident){
      lampState('','No stored memory matches that yet.');
      lampResult.innerHTML='This one is not in memory. <strong>Get a free token</strong> and it will be after the first call.';
      lampResult.classList.add('show');
    }else{
      // The probe could not establish an answer -- too few words, or the lookup
      // failed. Stay dark and show no verdict at all. Claiming "not in memory"
      // here would be the exact false negative the lamp exists to avoid.
      lampState('','Could not check memory right now.');
    }
  }catch(e){
    lampState('','Could not reach the memory service.');
  }
  btn.disabled=false;
});

/* --- live-site carousel --- */
const SITES=[
  {name:'DeckerGUI',url:'https://deckergui.my',icon:'fa-globe',allow:true},
  {name:'CTECX',url:'https://ctecx.deckergui.my',icon:'fa-diagram-project',allow:true},
  // Replaces krackeddevs.com, which sends X-Frame-Options: DENY plus CSP
  // frame-ancestors 'none' and could therefore only ever render as a blank box.
  // Verified 200 with neither header, so this one embeds.
  {name:'Agent KD Skill',url:'https://agent-kd-skill.ctaxnagomi.workers.dev/',icon:'fa-code',allow:true},
  {name:'DGUI App',url:'https://app.deckergui.my',icon:'fa-key',allow:true},
  {name:'DeckerGUI Guild',url:'https://portfolios.deckergui.my',icon:'fa-id-badge',allow:true},
  {name:'CORPUSLIB',url:'https://corpuslib-ui.deckergui.my',icon:'fa-book-open',allow:true}
];

// The logical viewport each embedded site is laid out at. The frame is rendered
// at this size and then scaled down with a CSS transform, which is what makes a
// cross-origin site render whole and scrollbar-free inside a small card: the
// page never overflows, because it is not being squeezed into 320px.
const FRAME_W=1280, FRAME_H=800;

function escAttr(v){return String(v).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

(function buildRail(){
  const track=document.getElementById('live-track');
  const inner=document.getElementById('live-inner');
  if(!track||!inner) return;
  inner.innerHTML=SITES.map(function(s){
    const esc=escAttr(s.url);
    const frame=s.allow
      ?'<div class="live-viewport">'
        +'<iframe class="live-frame" src="'+esc+'" loading="lazy" referrerpolicy="no-referrer" scrolling="no" sandbox="allow-scripts allow-same-origin allow-popups allow-forms" title="'+escAttr(s.name)+'"></iframe>'
        // Covers the nested page\'s scrollbar, which the parent cannot style.
        // Safe only because .live-viewport is pointer-events:none, so the frame
        // underneath is frozen and never scrolls behind the mask.
        +'<div class="live-mask live-mask-r"></div><div class="live-mask live-mask-b"></div>'
      +'</div>'
      :'';
    const blocked=s.allow?'':'<div class="live-blocked"><i class="fas fa-external-link-alt"></i><p>'+escAttr(s.reason||'')+'<br>Open it in a new tab.</p></div>';
    // "open" expands the card and deliberately does not navigate. The separate
    // external-link anchor is the only control that leaves the page, so the
    // gesture and the label never disagree about what a click will do.
    const open=s.allow
      ?'<button class="live-open" type="button" data-open aria-expanded="false" aria-label="Expand '+escAttr(s.name)+' preview">open</button>'
      :'<span class="live-open" style="opacity:.5;cursor:default">open</span>';
    return '<div class="live-card'+(s.allow?'':' blocked')+'" data-site="'+escAttr(s.name)+'">'+frame+blocked
      +'<div class="live-head"><i class="fas '+s.icon+'"></i>'+escAttr(s.name)
      +'<span class="live-actions">'+open
      +'<a class="live-out" href="'+esc+'" target="_blank" rel="noopener noreferrer" title="Open '+escAttr(s.name)+' in a new tab" aria-label="Open '+escAttr(s.name)+' in a new tab"><i class="fas fa-arrow-up-right-from-square"></i></a>'
      +'</span></div></div>';
  }).join('');
})();

// Scale every embedded frame to its own card width. Each viewport is observed
// individually rather than the track, because the width that matters is the
// card's -- and a card expanding does not resize the track, so an observer on
// the track never fires and the frame would sit letterboxed in the extra space.
(function fitFrames(){
  const track=document.getElementById('live-track');
  if(!track||!window.ResizeObserver) return;
  const fitOne=function(vp){
    const f=vp.querySelector('.live-frame');
    if(!f) return;
    const w=vp.clientWidth;
    if(!w) return;
    const k=w/FRAME_W;
    f.style.transform='scale('+k+')';
    // The frame is a fixed 800px tall; scaling width alone would leave the
    // bottom of the scaled page short of the viewport, showing a gap.
    vp.style.height=Math.round(FRAME_H*k)+'px';
  };
  const fitAll=function(){track.querySelectorAll('.live-viewport').forEach(fitOne);};
  const ro=new ResizeObserver(function(entries){
    entries.forEach(function(e){fitOne(e.target);});
  });
  track.querySelectorAll('.live-viewport').forEach(function(vp){ro.observe(vp);});
  window.addEventListener('resize',fitAll);
  // Refit once the initial paint is done: a card's own content can settle after
  // first layout and leave a width measured too early.
  window.addEventListener('load',fitAll);
  fitAll();
  setTimeout(fitAll,600);
})();

// Wheel, drag and tap, with the feel of a native iOS carousel: velocity-tracked
// drag, momentum on release, resistance past either end, and a settle onto the
// nearest card. Vertical page scrolling is left entirely alone (touch-action:
// pan-y plus a single axis lock), so the rail can never trap the scroll.
(function railGestures(){
  const rail=document.getElementById('live-rail');
  const track=document.getElementById('live-track');
  if(!rail||!track) return;

  const reduced=function(){return window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;};
  const maxScroll=function(){return Math.max(0,track.scrollWidth-track.clientWidth);};
  const inner=document.getElementById('live-inner');

  // iOS resistance curve. Asymptotic, so a long pull keeps moving but can never
  // run the rail away from its bounds.
  const rubber=function(over,dim){
    const c=0.55;
    return (over*dim*c)/(dim+c*Math.abs(over));
  };
  // Overscroll has to be a transform, not a scroll position: scrollLeft is
  // clamped to [0, max] in a LTR scroller, so an earlier version of this that set
  // scrollLeft past the end did nothing at all -- the pull simply snapped back
  // with no give. Signed so pulling right at the start reveals space on the left.
  let shift=0;
  const setShift=function(px){
    shift=px;
    if(inner) inner.style.transform=px?'translateX('+px+'px)':'';
  };
  const setScroll=function(x){
    const max=maxScroll();
    if(x<0){track.scrollLeft=0;setShift(-rubber(x,track.clientWidth));}
    else if(x>max){track.scrollLeft=max;setShift(-rubber(x-max,track.clientWidth));}
    else{track.scrollLeft=x;setShift(0);}
  };

  // --- wheel: only hijack while the rail still has room in that direction, so
  // vertical page scrolling resumes the moment the rail is exhausted.
  rail.addEventListener('wheel',function(ev){
    if(ev.ctrlKey) return;                       // leave pinch-zoom alone
    if(Math.abs(ev.deltaY)<=Math.abs(ev.deltaX)) return;  // let real horizontal input through
    const max=maxScroll();
    if(max<=0) return;
    const atStart=track.scrollLeft<=0;
    const atEnd=track.scrollLeft>=max-1;
    if((ev.deltaY<0&&atStart)||(ev.deltaY>0&&atEnd)) return;
    ev.preventDefault();
    track.scrollLeft+=ev.deltaY;
  },{passive:false});

  // --- velocity tracking -------------------------------------------------
  let pid=null,sx=0,sy=0,sl=0,axis=null,dragging=false,raf=0,vel=0,movedFar=false,samples=[],glideStart=0;
  const nowMs=function(){return (window.performance&&performance.now)?performance.now():Date.now();};
  const pushSample=function(t,x){samples.push([t,x]);if(samples.length>6)samples.shift();};
  const velocity=function(){
    if(samples.length<2) return 0;
    const first=samples[0],last=samples[samples.length-1];
    const dt=last[0]-first[0];
    if(dt<=0) return 0;
    return (last[1]-first[1])/dt*16;              // px per frame
  };
  const stopGlide=function(){if(raf){cancelAnimationFrame(raf);raf=0;}};

  // Centre of whichever card is nearest, clamped into range.
  const snapTarget=function(){
    const cards=track.querySelectorAll('.live-card');
    if(!cards.length) return null;
    const mid=track.scrollLeft+track.clientWidth/2;
    let best=null,bd=Infinity;
    cards.forEach(function(c){
      const d=Math.abs(c.offsetLeft+c.offsetWidth/2-mid);
      if(d<bd){bd=d;best=c;}
    });
    if(!best) return null;
    return Math.max(0,Math.min(maxScroll(),best.offsetLeft-(track.clientWidth-best.offsetWidth)/2));
  };

  // Snap is animated by hand rather than with scrollTo({behavior:'smooth'}).
  // The browser's mandatory snap is switched OFF for the whole animation via
  // .dragging and only handed back once we are already on a card boundary;
  // re-enabling it first and then scrolling made the two fight, and the rail came
  // to rest between cards.
  const settle=function(){
    const max=maxScroll();
    const clamped=Math.min(max,Math.max(0,track.scrollLeft));
    track.scrollLeft=clamped;
    if(shift){
      // Ease the overscroll back to zero rather than snapping it away.
      track.classList.add('settling');
      setShift(0);
      setTimeout(function(){track.classList.remove('settling');},320);
    }
    const target=snapTarget();
    if(target===null||Math.abs(target-clamped)<=1){track.classList.remove('dragging');return;}
    if(reduced()){track.scrollLeft=target;track.classList.remove('dragging');return;}
    const from=clamped,dist=target-from,t0=nowMs(),DUR=280;
    const step=function(){
      const p=Math.min(1,(nowMs()-t0)/DUR);
      const e=1-Math.pow(1-p,3);
      track.scrollLeft=from+dist*e;
      if(p<1){requestAnimationFrame(step);return;}
      track.scrollLeft=target;                 // land exactly on the boundary
      track.classList.remove('dragging');      // only now does mandatory snap resume
    };
    requestAnimationFrame(step);
  };

  // A glide must always be over quickly. Pure exponential decay from a fast
  // flick ran past 1.5s, which reads as the carousel being stuck, so the
  // velocity is capped, decay is steepened, and the glide has a hard time limit.
  // iOS settles in well under half a second.
  const glide=function(){
    if(!glideStart) glideStart=nowMs();
    const next=track.scrollLeft+vel;
    setScroll(next);
    // Bleed harder against a wall than in open water, so hitting the end feels
    // like arriving rather than like a collision.
    vel*=Math.abs(shift)>0.5?0.3:0.9;
    if(Math.abs(vel)<0.5||nowMs()-glideStart>650){raf=0;glideStart=0;settle();return;}
    raf=requestAnimationFrame(glide);
  };

  track.addEventListener('pointerdown',function(ev){
    if(ev.pointerType==='mouse'&&ev.button!==0) return;
    // The header controls own their own clicks; a drag must not start on them.
    if(ev.target&&ev.target.closest&&ev.target.closest('[data-open],.live-out')) return;
    pid=ev.pointerId;sx=ev.clientX;sy=ev.clientY;sl=track.scrollLeft;
    axis=null;movedFar=false;vel=0;samples=[[ev.timeStamp,sl]];
    // A new touch cancels any in-flight settle, and clears a leftover overscroll
    // so the row does not start the gesture visually out of position.
    stopGlide();
    track.classList.remove('settling');
    if(shift) setShift(0);
  });

  window.addEventListener('pointermove',function(ev){
    if(ev.pointerId!==pid) return;
    const dx=ev.clientX-sx,dy=ev.clientY-sy;
    if(axis===null){
      if(Math.abs(dx)<4&&Math.abs(dy)<4) return;
      // Lock the axis once, like a native scroller. A diagonal swipe would
      // otherwise flip between the rail and the page and feel broken.
      axis=Math.abs(dx)>Math.abs(dy)?'x':'y';
      if(axis==='x'){
        dragging=true;
        track.classList.add('dragging');
        try{track.setPointerCapture(pid);}catch(e){}
      }
    }
    if(axis!=='x'||!dragging) return;
    ev.preventDefault();
    movedFar=Math.abs(dx)>6;
    setScroll(sl-dx);
    pushSample(ev.timeStamp,track.scrollLeft);
  },{passive:false});

  const endDrag=function(ev){
    if(ev&&ev.pointerId!==pid) return;
    if(!dragging){pid=null;axis=null;return;}
    dragging=false;pid=null;axis=null;
    // A pause before lifting the finger means the user parked the rail, not
    // flicked it. Sampling stale positions would otherwise fling it anyway.
    const last=samples.length?samples[samples.length-1][0]:0;
    vel=(ev&&ev.timeStamp-last<90)?velocity():0;
    // Cap the launch speed. A 5-sample window can produce an absurd px/frame from
    // a fast synthetic or jittery flick, and an uncapped one overshoots the whole
    // rail before the decay bites.
    vel=Math.max(-45,Math.min(45,vel));
    if(reduced()||!vel){track.classList.remove('dragging');settle();return;}
    track.classList.add('dragging');
    raf=requestAnimationFrame(glide);
  };
  window.addEventListener('pointerup',endDrag);
  window.addEventListener('pointercancel',endDrag);

  // --- expand / collapse, and click suppression after a drag -------------
  track.addEventListener('click',function(ev){
    if(movedFar){movedFar=false;ev.preventDefault();ev.stopPropagation();return;}
    const btn=ev.target&&ev.target.closest&&ev.target.closest('[data-open]');
    if(!btn) return;
    const card=btn.closest('.live-card');
    if(!card) return;
    const wide=card.classList.toggle('wide');
    const name=card.dataset.site||'this';
    btn.setAttribute('aria-expanded',wide?'true':'false');
    btn.setAttribute('aria-label',(wide?'Collapse ':'Expand ')+name+' preview');
  });

  // Arrow keys move the rail a card at a time for keyboard users, since the
  // scrollbar is hidden and there is nothing else to grab.
  rail.addEventListener('keydown',function(ev){
    if(ev.key!=='ArrowRight'&&ev.key!=='ArrowLeft') return;
    const cards=track.querySelectorAll('.live-card');
    if(!cards.length) return;
    const mid=track.scrollLeft+track.clientWidth/2;
    let idx=0,bd=Infinity;
    cards.forEach(function(c,i){const d=Math.abs(c.offsetLeft+c.offsetWidth/2-mid);if(d<bd){bd=d;idx=i;}});
    const dir=ev.key==='ArrowRight'?1:-1;
    const next=cards[Math.max(0,Math.min(cards.length-1,idx+dir))];
    if(!next) return;
    ev.preventDefault();
    const left=Math.max(0,Math.min(maxScroll(),next.offsetLeft-(track.clientWidth-next.offsetWidth)/2));
    if(track.scrollTo) track.scrollTo({left:left,behavior:reduced()?'auto':'smooth'});
  });
})();

