"""DGUI-HyperMem Memory Provider for Hermes Agent.

Wraps the DGUI-HyperMem API (https://dgui-hmem.deckergui.my) as a native
Hermes MemoryProvider so recall/capture happen automatically.
"""

from __future__ import annotations

import json
import logging
import os
import threading
import time
from pathlib import Path
from typing import Any, Dict, List, Optional
from urllib import error as urlerror
from urllib import request as urlrequest

from agent.memory_provider import MemoryProvider, RecallStatus, spawn_context_thread
from agent.secret_scope import get_secret

logger = logging.getLogger(__name__)

DEFAULT_URL = "https://dgui-hmem.deckergui.my"
TIMEOUT = 10

TRIVIAL = {
    "hi", "hey", "hello", "yo", "sup", "ok", "okay", "yes", "no", "thanks", "thank you",
    "sure", "yep", "nope", "yeah", "nah", "cool", "nice", "great", "done", "next", "lgtm",
    "got it", "continue", "go ahead", "do it", "proceed",
}


class DGUIHyperMemClient:
    def __init__(self, base_url: str, token: str):
        self.base_url = base_url.rstrip("/")
        self.token = token

    def _headers(self) -> Dict[str, str]:
        h = {"Content-Type": "application/json", "Accept": "application/json"}
        if self.token:
            h["Authorization"] = f"Bearer {self.token}"
        return h

    def _post(self, path: str, payload: Dict[str, Any]) -> Dict[str, Any]:
        url = f"{self.base_url}{path}"
        data = json.dumps(payload).encode("utf-8")
        req = urlrequest.Request(url, data=data, headers=self._headers(), method="POST")
        try:
            with urlrequest.urlopen(req, timeout=TIMEOUT) as resp:
                body = resp.read().decode("utf-8")
                return json.loads(body) if body else {}
        except urlerror.HTTPError as e:
            try:
                body = e.read().decode("utf-8")
                return {"error": f"http_{e.code}", "detail": body[:200]}
            except Exception:
                return {"error": f"http_{e.code}"}
        except Exception as e:
            return {"error": str(e)}

    def _get(self, path: str) -> Dict[str, Any]:
        url = f"{self.base_url}{path}"
        req = urlrequest.Request(url, headers=self._headers(), method="GET")
        try:
            with urlrequest.urlopen(req, timeout=TIMEOUT) as resp:
                body = resp.read().decode("utf-8")
                return json.loads(body) if body else {}
        except urlerror.HTTPError as e:
            try:
                body = e.read().decode("utf-8")
                return {"error": f"http_{e.code}", "detail": body[:200]}
            except Exception:
                return {"error": f"http_{e.code}"}
        except Exception as e:
            return {"error": str(e)}

    def search(self, query: str, limit: int = 5, scope: str = "default") -> Dict[str, Any]:
        return self._post("/api/search", {"query": query, "limit": limit, "scope": scope})

    def add(self, content: str, scope: str = "default", metadata: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        payload = {"content": content, "scope": scope}
        if metadata:
            payload["metadata"] = metadata
        return self._post("/api/add", payload)

    def list(self, limit: int = 20, scope: str = "default") -> Dict[str, Any]:
        return self._post("/api/list", {"limit": limit, "scope": scope})

    def profile(self) -> Dict[str, Any]:
        return self._post("/api/profile", {})

    def forget(self, memory_id: str) -> Dict[str, Any]:
        return self._post("/api/forget", {"id": memory_id})


class DGUIHyperMemProvider(MemoryProvider):
    def __init__(self):
        self._base_url = DEFAULT_URL
        self._token = ""
        self._scope = "default"
        self._client: Optional[DGUIHyperMemClient] = None
        self._session_id = ""
        self._hermes_home = ""
        self._last_prefetch = ""
        self._last_count = 0
        self._sync_thread: Optional[threading.Thread] = None

    @property
    def name(self) -> str:
        return "dgui-hypermem"

    def is_available(self) -> bool:
        token = get_secret("DGUI_HYPERMEM_TOKEN") or os.environ.get("DGUI_HYPERMEM_TOKEN", "")
        url = os.environ.get("DGUI_HYPERMEM_URL") or DEFAULT_URL
        if not token:
            return False
        try:
            c = DGUIHyperMemClient(url, token)
            h = c._get("/health")
            return h.get("status") == "ok" or "name" in h
        except Exception:
            return bool(token)

    def unavailable_reason(self) -> str:
        if not (get_secret("DGUI_HYPERMEM_TOKEN") or os.environ.get("DGUI_HYPERMEM_TOKEN", "")):
            return "Set DGUI_HYPERMEM_TOKEN (and optionally DGUI_HYPERMEM_URL)."
        return "Cannot reach DGUI-HyperMem at the configured URL."

    def initialize(self, session_id: str, **kwargs) -> None:
        self._session_id = session_id
        self._hermes_home = kwargs.get("hermes_home", "")
        self._base_url = os.environ.get("DGUI_HYPERMEM_URL") or DEFAULT_URL
        self._token = get_secret("DGUI_HYPERMEM_TOKEN") or os.environ.get("DGUI_HYPERMEM_TOKEN", "")
        cfg_path = Path(self._hermes_home) / "dgui-hypermem.json" if self._hermes_home else None
        if cfg_path and cfg_path.exists():
            try:
                cfg = json.loads(cfg_path.read_text())
                if cfg.get("url"):
                    self._base_url = cfg["url"]
                if cfg.get("scope"):
                    self._scope = cfg["scope"]
            except Exception:
                pass
        self._client = DGUIHyperMemClient(self._base_url, self._token)
        logger.info("DGUI-HyperMem provider initialized (url=%s)", self._base_url)

    def system_prompt_block(self) -> str:
        return (
            "## DGUI-HyperMem (persistent memory)\n"
            "You have access to long-term hybrid memory via DGUI-HyperMem. "
            "Relevant memories are injected automatically; use dgui_search to recall explicitly "
            "or dgui_add to store important facts/preferences/decisions."
        )

    def prefetch(self, query: str, *, session_id: str = "") -> str:
        if not self._client or not query:
            self._last_prefetch = ""
            self._last_count = 0
            return ""
        q = query.strip().lower()
        if q in TRIVIAL or len(q) < 3:
            self._last_prefetch = ""
            self._last_count = 0
            return ""
        try:
            res = self._client.search(query=query, limit=5, scope=self._scope)
            if res.get("error"):
                self._last_prefetch = ""
                self._last_count = 0
                return ""
            items = res.get("results") or res.get("memories") or []
            if not items:
                self._last_prefetch = ""
                self._last_count = 0
                return ""
            lines = ["### Relevant memories (DGUI-HyperMem)"]
            for it in items[:5]:
                txt = it.get("content") or it.get("text") or ""
                if not txt:
                    continue
                mtype = it.get("type") or "fact"
                sal = it.get("salience")
                head = f"- [{mtype}] {txt}"
                if sal is not None:
                    head += f" (salience {sal})"
                lines.append(head)
            ctx = "\n".join(lines)
            self._last_prefetch = ctx
            self._last_count = len([l for l in lines if l.startswith("- [")])
            return ctx
        except Exception as e:
            logger.debug("dgui-hypermem prefetch failed: %s", e)
            self._last_prefetch = ""
            self._last_count = 0
            return ""

    def recall_status(self) -> Optional[RecallStatus]:
        if not self._last_prefetch:
            return None
        return RecallStatus(provider_label="dgui-hypermem", count=self._last_count, glyph="🧠")

    def sync_turn(self, user_content: str, assistant_content: str, *, session_id: str = "", messages: Optional[List[Dict[str, Any]]] = None) -> None:
        if not self._client:
            return
        u = (user_content or "").strip()
        a = (assistant_content or "").strip()
        if len(u) < 10 and len(a) < 10:
            return

        def _sync():
            try:
                snippet = f"User: {u[:400]}\nAssistant: {a[:600]}"
                self._client.add(
                    content=snippet,
                    scope=self._scope,
                    metadata={"source": "hermes", "session_id": session_id or self._session_id},
                )
            except Exception as e:
                logger.debug("dgui-hypermem sync_turn failed: %s", e)

        if self._sync_thread and self._sync_thread.is_alive():
            try:
                self._sync_thread.join(timeout=2.0)
            except Exception:
                pass
        self._sync_thread = spawn_context_thread(_sync, name="dgui-hypermem-sync")
        self._sync_thread.start()

    def on_session_end(self, messages: List[Dict[str, Any]]) -> None:
        if not self._client or not messages:
            return

        def _end():
            try:
                parts = []
                for m in messages[-12:]:
                    role = m.get("role", "")
                    content = m.get("content") or ""
                    if isinstance(content, list):
                        content = " ".join(str(c.get("text", "")) for c in content if isinstance(c, dict))
                    if content:
                        parts.append(f"{role}: {str(content)[:200]}")
                if not parts:
                    return
                self._client.add(
                    content="Session summary:\n" + "\n".join(parts),
                    scope=self._scope,
                    metadata={"source": "hermes", "kind": "session_end", "session_id": self._session_id},
                )
            except Exception as e:
                logger.debug("dgui-hypermem on_session_end failed: %s", e)

        t = spawn_context_thread(_end, name="dgui-hypermem-session-end")
        t.start()

    def on_pre_compress(self, messages: List[Dict[str, Any]]) -> str:
        if not self._client or not messages:
            return ""
        try:
            facts = []
            for m in messages[-8:]:
                content = m.get("content") or ""
                if isinstance(content, list):
                    content = " ".join(str(c.get("text", "")) for c in content if isinstance(c, dict))
                s = str(content).strip()
                if len(s) > 40 and m.get("role") in ("user", "assistant"):
                    facts.append(s[:150])
            if facts:
                self._client.add(
                    content="Pre-compress key points:\n" + "\n".join(f"- {f}" for f in facts),
                    scope=self._scope,
                    metadata={"source": "hermes", "kind": "pre_compress", "session_id": self._session_id},
                )
        except Exception as e:
            logger.debug("dgui-hypermem on_pre_compress failed: %s", e)
        return ""

    def get_tool_schemas(self) -> List[Dict[str, Any]]:
        return [
            {
                "name": "dgui_search",
                "description": "Search DGUI-HyperMem for relevant memories",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "query": {"type": "string", "description": "Search query"},
                        "limit": {"type": "integer", "default": 10},
                    },
                    "required": ["query"],
                },
            },
            {
                "name": "dgui_add",
                "description": "Add a memory to DGUI-HyperMem",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "content": {"type": "string", "description": "Memory content to store"},
                    },
                    "required": ["content"],
                },
            },
            {
                "name": "dgui_list",
                "description": "List recent memories from DGUI-HyperMem",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "limit": {"type": "integer", "default": 20},
                    },
                },
            },
            {
                "name": "dgui_profile",
                "description": "Get DGUI-HyperMem profile/stats",
                "parameters": {"type": "object", "properties": {}},
            },
            {
                "name": "dgui_forget",
                "description": "Forget/remove a memory by ID",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "memory_id": {"type": "string", "description": "Memory ID to forget"},
                    },
                    "required": ["memory_id"],
                },
            },
        ]

    def handle_tool_call(self, tool_name: str, args: Dict[str, Any], **kwargs) -> str:
        if not self._client:
            return json.dumps({"error": "not initialized"})
        try:
            if tool_name == "dgui_search":
                res = self._client.search(query=args.get("query", ""), limit=int(args.get("limit", 10)), scope=self._scope)
                return json.dumps(res)
            elif tool_name == "dgui_add":
                res = self._client.add(content=args.get("content", ""), scope=self._scope)
                return json.dumps(res)
            elif tool_name == "dgui_list":
                res = self._client.list(limit=int(args.get("limit", 20)), scope=self._scope)
                return json.dumps(res)
            elif tool_name == "dgui_profile":
                res = self._client.profile()
                return json.dumps(res)
            elif tool_name == "dgui_forget":
                res = self._client.forget(args.get("memory_id", ""))
                return json.dumps(res)
            else:
                return json.dumps({"error": f"unknown tool {tool_name}"})
        except Exception as e:
            return json.dumps({"error": str(e)})

    def get_config_schema(self) -> List[Dict[str, Any]]:
        return [
            {
                "key": "url",
                "description": "DGUI-HyperMem base URL",
                "default": DEFAULT_URL,
                "required": True,
            },
            {
                "key": "api_key",
                "description": "DGUI-HyperMem API token",
                "secret": True,
                "required": True,
                "env_var": "DGUI_HYPERMEM_TOKEN",
                "url": "https://hmem-admin.deckergui.my/",
            },
            {
                "key": "scope",
                "description": "Memory scope/namespace",
                "default": "default",
            },
        ]

    def save_config(self, values: Dict[str, Any], hermes_home: str) -> None:
        cfg_path = Path(hermes_home) / "dgui-hypermem.json"
        out = {}
        if values.get("url"):
            out["url"] = values["url"]
        if values.get("scope"):
            out["scope"] = values["scope"]
        try:
            cfg_path.write_text(json.dumps(out, indent=2))
        except Exception as e:
            logger.warning("Failed to save dgui-hypermem config: %s", e)


def register(ctx) -> None:
    ctx.register_memory_provider(DGUIHyperMemProvider())

