111: /* Invisible scrollbar, all engines. The rail is still keyboard-scrollable. */
112: .live-track{scrollbar-width:none;-ms-overflow-style:none}
113: .live-track::-webkit-scrollbar{width:0;height:0;display:none}
114: /* pan-y keeps vertical page scrolling native and hands horizontal movement to
115:    the gesture handler below, so a swipe never has to fight the page. */
116: .live-track{touch-action:pan-y}
117: .live-track.dragging{cursor:grabbing;scroll-behavior:auto;scroll-snap-type:none;user-select:none;-webkit-user-select:none}
118: /* The card row lives in an inner element because scrollLeft is clamped to
119:    [0, max] in a LTR scroller, so a pull past either end cannot be expressed as a
120:    scroll position at all. The overscroll is a transform on this element instead,
121:    which is also why it does not fight .live-card:hover's transform. */
122: .live-inner{display:flex;gap:14px;width:max-content;min-width:100%;will-change:transform}
123: .live-track.dragging .live-inner{transition:none}
124: .live-track.settling .live-inner{transition:transform .3s cubic-bezier(.2,.9,.3,1)}
125: .live-card{flex:0 0 auto;width:min(320px,78vw);scroll-snap-align:center;border-radius:16px;overflow:hidden;border:1px solid var(--border-glass);background:var(--glass);box-shadow:var(--shadow);transition:border-color .25s,transform .25s,width .32s cubic-bezier(.34,1.3,.5,1);position:relative}
126: /* Clicking "open" grows the card in place. It never navigates, so the reader
127:    stays on the landing page and the rail keeps its place. */
128: .live-card.wide{width:min(520px,88vw)}
129: .live-card:hover{border-color:var(--accent-cyan);transform:translateY(-2px)}
130: /* iOS glass: a translucent ring over the live content, with an inset top
131:    highlight and a soft outer bloom, so the frame reads as glass rather than as
132:    a bordered box. Sits above the iframe, which is itself opaque. */
133: .live-card::after{content:'';position:absolute;inset:0;border-radius:16px;pointer-events:none;z-index:3;
134:   background:linear-gradient(160deg,rgba(255,255,255,.14),rgba(255,255,255,.02) 38%,rgba(255,255,255,0) 60%);
135:   box-shadow:inset 0 1px 0 rgba(255,255,255,.28),inset 0 0 0 1px rgba(255,255,255,.07),inset 0 -18px 30px -18px rgba(0,0,0,.55)}
136: /* The frame area: a fixed logical desktop viewport, scaled down to fit. The
137:    inner site therefore lays out at 1280x800, which is what removes its own
138:    scrollbar -- a cross-origin iframe's inner scrollbar cannot be styled away
139:    from the parent, but it does not appear if the page fits the viewport. */
140: .live-viewport{position:relative;width:100%;aspect-ratio:1280/800;overflow:hidden;border-radius:15px 15px 0 0;background:#0b1220;isolation:isolate}
141: .live-frame{position:absolute;top:0;left:0;width:1280px;height:800px;border:0;display:block;background:#0b1220;transform-origin:top left;pointer-events:none}
142: /* Interaction stays with the card, so a drag can never start inside the iframe,
143:    whose document would swallow the pointer events. This also freezes the
144:    embedded page, which is what makes the scrollbar mask below safe: there is no
145:    scrolling underneath it for the mask to ever cover up. */
146: .live-viewport{pointer-events:none}
147: /* Most of these pages are far taller than the 800px logical viewport (ctecx is
148:    ~5500px, agent-kd-skill ~34500px), and this platform draws classic
149:    space-taking scrollbars, so the nested page really does render one. It cannot
150:    be styled from the parent -- a cross-origin document's scrollbar is not
151:    reachable by CSS. So it is covered instead: a soft gradient down the right
152:    edge and along the bottom, wide enough to cover a 15px logical scrollbar at
153:    every card width, and shaped to read as a vignette rather than a patch. */
154: .live-mask{position:absolute;pointer-events:none;z-index:2}
155: .live-mask-r{top:0;right:0;bottom:0;width:9px;background:linear-gradient(to left,rgba(8,13,24,.92),rgba(8,13,24,0))}
156: .live-mask-b{left:0;right:0;bottom:0;height:7px;background:linear-gradient(to top,rgba(8,13,24,.92),rgba(8,13,24,0))}
157: .live-head{display:flex;align-items:center;gap:8px;padding:10px 12px;font-size:12px;color:var(--text-secondary);position:relative;z-index:4}
158: .live-head i{color:var(--accent-cyan);font-size:11px}
