160: .live-open{font:inherit;font-size:10px;color:var(--text-muted);background:rgba(255,255,255,.06);border:1px solid var(--border-glass);border-radius:999px;padding:3px 9px;cursor:pointer;transition:color .2s,background .2s,border-color .2s}
161: .live-open:hover{color:var(--accent-cyan);background:rgba(34,199,220,.12);border-color:var(--accent-cyan)}
162: .live-open[aria-expanded="true"]{color:var(--accent-cyan);background:rgba(34,199,220,.16);border-color:var(--accent-cyan)}
163: .live-out{font-size:11px;color:var(--text-muted);text-decoration:none;padding:2px;border-radius:6px;line-height:1}
164: .live-out:hover{color:var(--accent-cyan)}
165: /* Fallback card for a site that sends X-Frame-Options / frame-ancestors. */
166: .live-card.blocked .live-viewport{display:none}
167: .live-blocked{display:none;aspect-ratio:1280/800;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:20px;text-align:center;background:linear-gradient(160deg,rgba(21,31,53,.9),rgba(12,20,36,.9))}
